def eksik_modulleri_otomatik_olustur(zorla_yenile: bool = False):
    surum_dosyasi = os.path.join(PROJE_KOK_DIZINI, ".ar_modul_surum")
    surum_guncel_mi = False
    if os.path.exists(surum_dosyasi):
        try:
            with open(surum_dosyasi, "r", encoding="utf-8") as sf:
                surum_guncel_mi = (sf.read().strip() == _MODUL_SURUM_ETIKETI)
        except Exception:
            surum_guncel_mi = False

    for dosya_adi, b64_veri in _GOMULU_MODUL_ARSIVI.items():
        hedef_yol = os.path.join(PROJE_KOK_DIZINI, dosya_adi)
        if zorla_yenile or (not surum_guncel_mi) or (not os.path.exists(hedef_yol)) or os.path.getsize(hedef_yol) < 100:
            try:
                cozulen_kod = zlib.decompress(base64.b64decode(b64_veri)).decode("utf-8")
                with open(hedef_yol, "w", encoding="utf-8") as f_out:
                    f_out.write(cozulen_kod)
            except Exception:
                pass

    try:
        with open(surum_dosyasi, "w", encoding="utf-8") as sf:
            sf.write(_MODUL_SURUM_ETIKETI)
    except Exception:
        pass


eksik_modulleri_otomatik_olustur(zorla_yenile=False)


# 5. KENDİNİ ONARAN (SELF-HEALING) VE BÜTÜNLÜK KONTROLLÜ MERKEZİ MODÜL BAĞLAYICI
def _tek_modulu_arsivden_onar(modul_adi: str) -> str:
    dosya_adi = f"{modul_adi}.py"
    hedef_yol = os.path.join(PROJE_KOK_DIZINI, dosya_adi)
    b64_veri = _GOMULU_MODUL_ARSIVI.get(dosya_adi)
    if b64_veri:
        cozulen = zlib.decompress(base64.b64decode(b64_veri)).decode("utf-8")
        with open(hedef_yol, "w", encoding="utf-8") as f_out:
            f_out.write(cozulen)
    return hedef_yol


def modulu_bagla(modul_adi: str):
    """
    1. Modülü doğrudan proje kökünden yükler; dosya eksik veya sözdizimi bozulmuşsa
       gömülü arşivden otomatik onarıp (self-healing) tekrar yükler.
    2. Yükleme sırasında hiçbir şekilde ham Traceback veya sistem yolu sızdırmaz.
    """
    if modul_adi in sys.modules and getattr(sys.modules[modul_adi], "__file__", None):
        return sys.modules[modul_adi]

    ana_yol = os.path.join(PROJE_KOK_DIZINI, f"{modul_adi}.py")
    if (not os.path.exists(ana_yol)) or os.path.getsize(ana_yol) < 100:
        ana_yol = _tek_modulu_arsivden_onar(modul_adi)

    for deneme in range(2):
        try:
            spec = importlib.util.spec_from_file_location(modul_adi, ana_yol)
            if spec and spec.loader:
                mod = importlib.util.module_from_spec(spec)
                sys.modules[modul_adi] = mod
                spec.loader.exec_module(mod)
                return mod
        except Exception:
            if deneme == 0:
                ana_yol = _tek_modulu_arsivden_onar(modul_adi)
            else:
                raise
    return __import__(modul_adi)


